def consolidate_employee_profiles(apps, schema_editor):
    Employee = apps.get_model('HRapp', 'Employee')
    StaffProfile = apps.get_model('core', 'StaffProfile')
    mapping = {}
    for employee in Employee.objects.all():
        if not employee.user_id:
            continue
        mapping[employee.pk] = employee.user_id
        profile = StaffProfile.objects.filter(pk=employee.user_id).first()
        if not profile:
            continue
        updates = {}
        if employee.staff_id and not profile.staff_reg_no:
            updates['staff_reg_no'] = employee.staff_id[:30]
        if employee.job_title and not profile.job_title:
            updates['job_title'] = employee.job_title[:150]
        if employee.category and not profile.category:
            updates['category'] = employee.category[:100]
        if employee.department_id and not profile.department_id:
            updates['department_id'] = employee.department_id
        if updates:
            StaffProfile.objects.filter(pk=profile.pk).update(**updates)

    for model_name in ('EmployeePersonalInfo', 'EmployeeAddress', 'EmployeeContact',
                       'EmergencyContact', 'Dependant', 'EducationHistory',
                       'WorkExperience', 'BankDetail'):
        model = apps.get_model('HRapp', model_name)
        for row in model.objects.all():
            if row.employee_id in mapping:
                row.employee_id = mapping[row.employee_id]
                row.save(update_fields=['employee'])

    Leave = apps.get_model('HRapp', 'Leave')
    for row in Leave.objects.all():
        if row.supervisor_id in mapping:
            row.supervisor_id = mapping[row.supervisor_id]
            row.save(update_fields=['supervisor'])

    for model_name in ('Appraisal', 'PerformanceImprovementPlan'):
        model = apps.get_model('appraisals', model_name)
        for row in model.objects.all():
            changed = False
            if row.employee_id in mapping:
                row.employee_id = mapping[row.employee_id]
                changed = True
            if hasattr(row, 'supervisor_id') and row.supervisor_id in mapping:
                row.supervisor_id = mapping[row.supervisor_id]
                changed = True
            if changed:
                row.save()


